export const BODY: string = "\n<p>سلسلة Base64 موجودة في حافظتك أو بريدك أو رد API، وتحتاج الصورة التي تحملها. التحويل يستغرق نحو دقيقة بمجرد أن تعرف الخطوات.</p>\n<p>هذا الدليل يأخذك خطوة بخطوة لتحويل Base64 إلى صورة في أربع خطوات: لصق السلسلة ومراجعة المعاينة واختيار صيغة التنزيل وحفظ الملف.</p>\n<p>لا برنامج للتثبيت ولا حساب للإنشاء ولا شيء يُرفع إلى أي مكان: تُفك السلسلة محليًا في متصفحك من البداية إلى النهاية.</p>\n<h2 id=\"what-you-need\">ما تحتاجه قبل أن تبدأ</h2>\n<p>تحتاج سلسلة Base64 نفسها، منسوخة بالكامل: سلسلة مقطوعة لا يمكن فكها، فتأكد من أن النسخة تشمل البداية والنهاية.</p>\n<p>اعرف ما الغرض من الصورة، لأن ذلك يقرر صيغة التنزيل: الأصل يحافظ على الملف الدقيق، وPNG يحافظ على الشفافية، وJPG يصغّر الصور الفوتوغرافية، وWebP هو الخيار الحديث والمضغوط. والمتصفح هو كل البرامج التي تحتاجها: تعمل الأداة في Chrome وSafari وFirefox وEdge، على الحاسوب والهاتف، دون أي إضافة.</p>\n<p>وإذا جاءت السلسلة ملفوفة في HTML أو CSS، يمكنك لصق كل شيء: فك التشفير يتسامح مع علامات الاقتباس وأغلفة url() حول السلسلة.</p>\n<h2 id=\"step-1-paste-the-string\">الخطوة 1: الصق سلسلة Base64</h2>\n<p>افتح <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك Base64 إلى صورة</a> والصق السلسلة في منطقة الإدخال: يبدأ فك التشفير تلقائيًا، دون أي زر للضغط عليه.</p>\n<p>تقبل الأداة سلاسل مع بادئة data:image أو دونها: URL بيانات كاملة من صفحة ويب وسلسلة خام من JSON تعملان كلاهما. والسلاسل الآمنة لـURL تعمل أيضًا: إذا استخدمت السلسلة شرطات وشرطات سفلية بدل زائد وشرطة مائلة، يتعرف المفكك على المتغير ويفكها بشكل صحيح.</p>\n<p>فواصل الأسطر والمسافات الإضافية تُتجاهل: سلسلة ملفوفة من عميل بريد أو ملصوقة بمسافات حولها تُفك مع ذلك دون أي تنظيف.</p>\n<h2 id=\"step-2-review-preview\">الخطوة 2: راجع المعاينة والمقاييس</h2>\n<p>تظهر الصورة المفككة فوق خلفية مربعات، بأبعادها وحجم ملفها بجانبها: تحقق من أن الصورة هي التي توقعتها.</p>\n<p>انظر إلى خلفية المربعات بعناية: المربعات الرمادية والبيضاء التي تُرى عبر الصورة تعني شفافية، وذلك يقرر إن كان JPG آمنًا للاستخدام. وراجع الأبعاد: أيقونة صغيرة مفككة من سلسلة هي صورة صغيرة، ولا صيغة تنزيل ستجعلها أكبر أو أحدة مما هي عليه.</p>\n<p>راجع حجم الملف الثنائي: يجب أن يكون نحو ثلاثة أرباع طول النص الذي لصقته، لأن فك التشفير يزيل الزيادة 33 بالمئة من الترميز.</p>\n<h2 id=\"step-3-choose-format\">الخطوة 3: اختر صيغة التنزيل</h2>\n<p>اختر الأصل عندما تريد الملف كما رُمّز بالضبط: هذا هو الخيار الأكثر أمانًا، خصوصًا لـGIF المتحركة وSVG المتجهة، التي تفقد خصائصها الخاصة عند التحويل.</p>\n<p>اختر PNG عندما تكون للصورة شفافية أو حواف حادة: يحافظ PNG على البكسلات بدقة ويبقي قناة ألفا، فتنجو الشعارات والأيقونات من الرحلة ذهابًا وإيابًا. واختر JPG عندما تكون الصورة فوتوغرافية وتريد أصغر ملف: يزيل JPG الشفافية، فاستخدمه فقط عندما لا تُظهر معاينة المربعات مناطق شفافة.</p>\n<p>اختر WebP عندما تكون الوجهة موقعًا حديثًا: إنه أصغر من PNG لمعظم الصور ويدعم الشفافية، ما يجعله خيارًا افتراضيًا جيدًا للاستخدام على الويب.</p>\n<h2 id=\"step-4-download\">الخطوة 4: نزّل ملف الصورة</h2>\n<p>انقر زر التنزيل: يُحفظ الملف باسم decoded_image بالامتداد المناسب لصيغتك المختارة، مثل decoded_image.png أو decoded_image.jpg.</p>\n<p>غيّر اسم الملف إلى شيء ذي معنى فورًا: مجلد مليء بملفات اسمها decoded_image مربك، بينما اسم مثل logo-empresa.png يخبرك ما هو بعد أشهر. وافتح الملف المنزّل وتأكد من أنه يبدو جيدًا: المعاينة في الأداة موثوقة، لكن مراجعة أخيرة للملف الحقيقي تكلف ثوانٍ وتكتشف أي سوء فهم.</p>\n<p>وإذا احتجت ترميز الصورة مجددًا بعدها، يأخذ <a href=\"/ar/tahwil-as-sura-ila-base64/\">مشفّر الصورة إلى Base64</a> الملف المنزّل وينتج سلسلة جديدة منه.</p>\n<h2 id=\"decoding-without-prefix\">كيف تفك سلسلة دون البادئة</h2>\n<p>كثير من السلاسل تصل دون بادئة data:image، خصوصًا من API وقواعد البيانات: يقرأ المفكك ترويسة الصورة لتحديد الصيغة، فالبادئة المفقودة ليست مشكلة.</p>\n<p>الصق السلسلة الخام كما هي: تكتشف الأداة إن كانت البايتات تصف ملف PNG أو JPG أو GIF أو WebP أو SVG أو BMP أو ICO، وتُظهر الصيغة المكتشفة بجانب المعاينة. وإذا اكتُشفت الصيغة خطأ، فترويسة الملف نفسها غير عادية: نزّل كأصل في تلك الحالة، وافحص الملف بعارض صور قبل تحويله.</p>\n<p>وعند مشاركة السلسلة، فكر في إضافة البادئة بنفسك: URL بيانات يصف نفسه، والشخص التالي الذي يستلمها سيعرف الصيغة دون تخمين.</p>\n<h2 id=\"decoding-url-safe-strings\">كيف تفك سلسلة آمنة لـURL</h2>\n<p>يستبدل Base64 الآمن لـURL الزائد بشرطة والشرطة المائلة بشرطة سفلية، لتستطيع السلسلة أن تكون داخل عنوان ويب دون هروب: تبدو شبه مطابقة لـBase64 القياسي.</p>\n<p>يقبل المفكك الأبجديتين دون تغيير أي ضبط: الصق السلسلة وتُفك، مهما كان المتغير الذي تستخدمه. وإذا لم تُفك سلسلة، راجع إن كان هناك خلط بين الأبجديتين: سلسلة محولة جزئيًا، ببعض علامات الزائد وبعض الشرطات، تالفة وتحتاج نسخة جديدة من المصدر.</p>\n<p>وقد يفقد الحشو أيضًا في السلاسل الآمنة لـURL، لأن بعض الأنظمة تزيل علامات المساواة من النهاية: يتسامح المفكك مع الحشو المفقود في معظم الحالات، لكن نسخة كاملة أفضل.</p>\n<h2 id=\"decoding-from-html-css\">كيف تفك سلسلة ملفوفة في HTML أو CSS</h2>\n<p>غالبًا تُنسخ السلاسل مع كودها حولها، مثل وسم صورة مع URL بيانات كمصدر، أو دالة CSS url() تلف القيمة.</p>\n<p>يمكنك لصق المقتطف كله: يتسامح المفكك مع علامات اقتباس HTML وأغلفة CSS url() حول السلسلة، ويستخرج محتوى Base64 من داخلها. وإذا فشل اللصق، أزل الغلاف بنفسك: انسخ فقط الجزء بين الفاصلة بعد base64 وعلامة الاقتباس الختامية، والصق تلك السلسلة النظيفة.</p>\n<p>لوسم صورة HTML، تكون السلسلة داخل سمة src بعد data:image/png;base64,. ولـCSS، تكون داخل أقواس url()، غالبًا ملفوفة بعلامات اقتباس.</p>\n<h2 id=\"converting-old-formats\">كيف تحول سلسلة BMP أو ICO قديمة إلى WebP</h2>\n<p>السلاسل القديمة لـfavicon وخريطة البتات تُفك إلى ملفات BMP أو ICO، وهي ضخمة وقليلة التوافق على الويب الحديث: تحويلها إلى WebP يصلح المشكلتين معًا.</p>\n<p>الصق السلسلة وانتظر المعاينة واختر WebP كصيغة تنزيل: تحول الأداة الصورة المفككة إلى ملف حديث ومضغوط. وراجع الشفافية أولًا: favicon ICO غالبًا له مناطق شفافة، وWebP يحافظ عليها، فيبدو الأيقونة المحولة مثل الأصل.</p>\n<p>ولـfavicon تحديدًا، فكر في التنزيل كـPNG: المتصفحات تقبل favicon PNG على نطاق واسع، والملف أبسط للإشارة إليه من HTML.</p>\n<h2 id=\"decoding-svg-to-png\">كيف تفك سلسلة SVG إلى ملف PNG</h2>\n<p>سلسلة SVG Base64 تُفك إلى كود متجه، وهو حاد بأي حجم لكنه غير مقبول في كل مكان: بعض المنصات تريد صورة نقطية، وPNG هو الخيار المعتاد.</p>\n<p>الصق السلسلة وتأكد من أن المعاينة تُظهر الرسم المتجه بشكل صحيح واختر PNG كصيغة تنزيل: تعرض الأداة SVG كـPNG بأبعاده الجوهرية. وPNG الناتج صورة بحجم ثابت، فلن يتكبر مثل SVG الأصلي: إذا احتاجت الوجهة صورة كبيرة، اعرضها بحجم أكبر قبل التنزيل، أو احتفظ بـSVG.</p>\n<p>وإذا كانت السلسلة URL بيانات SVG بسيطة دون وسم base64، ستفشل مع خطأ ترميز: تلك السلسلة ليست Base64 إطلاقًا، فاحفظ كود SVG مباشرة كملف .svg.</p>\n<h2 id=\"troubleshooting-corrupt-strings\">حل المشاكل: سلاسل تالفة</h2>\n<p>سلسلة لا تُفك غالبًا مقطوعة أو معدلة أو لم تكن صورة أبدًا: تُبلغ الأداة عن خطأ واضح بدل إنتاج ملف مكسور.</p>\n<p>راجع أولًا بداية السلسلة ونهايتها: القطع غالبًا يقطع الذيل، فسلسلة تنتهي منتصف كلمة أو دون حشوها هي علامة نسخة غير كاملة. وابحث عن أحرف لا تنتمي إلى Base64: أقواس زاوية أو علامات اقتباس داخل السلسلة أو URL بمعلمات إضافية تشير إلى أن النسخة التقطت نصًا محيطًا.</p>\n<p>وعندما يكون المصدر رد API، راجع إن كان الرد نفسه قُطع: JSON مقطوع ينتج سلسلة مقطوعة، وطلب جديد فقط يستطيع إصلاحها.</p>\n<h2 id=\"troubleshooting-svg-error\">حل المشاكل: خطأ ترميز SVG</h2>\n<p>يظهر خطأ ترميز SVG عندما تكون السلسلة الملصوقة URL بيانات SVG بسيطة بدل Base64: تحتوي وسوم SVG مقروءة بدل أحرف مرمزة.</p>\n<p>تعرّف عليه بالنظر إلى السلسلة: إذا استطعت قراءة كلمات مثل svg أو path أو rect داخلها، فالسلسلة كود SVG مرمز لـURL، لا Base64. وللحصول على الملف، انسخ كود SVG خارج URL البيانات، وفك أي هروب نسبة، واحفظ النتيجة كملف .svg في محرر نصوص.</p>\n<p>لا تحاول إجباره عبر المفكك: تتوقع الأداة أحرف Base64، ولا ضبط سيجعلها تقبل وسم SVG بسيط كسلسلة مرمزة.</p>\n<h2 id=\"clearing-and-next\">كيف تمسح الإدخال للسلسلة التالية</h2>\n<p>السلاسل الطويلة مزعجة للمسح يدويًا، فلدى الأداة زر مسح يفرغ الإدخال بنقرة واحدة: استخدمه بين عمليات الفك لبدء من جديد.</p>\n<p>امسح قبل لصق السلسلة التالية، لا بعدها: اللصق فوق سلسلة طويلة قد يترك شظايا من القديمة، ما يفسد فك التشفير الجديد. ونزّل الصورة الحالية قبل المسح: المسح يزيل السلسلة والمعاينة معًا، والصورة المفككة توجد فقط كملف منزّل بعد ذلك.</p>\n<p>العمل مع دفعة سلاسل سريع هكذا: الصق ونزّل وامسح والصق التالية، دون تمرير أو تحديد يدوي.</p>\n<h2 id=\"re-encoding-the-image\">كيف تعيد ترميز الصورة المنزّلة</h2>\n<p>أحيانًا تحتاج الصورة المفككة العودة إلى شكل نصي، مثلًا بعد تحويل BMP قديم إلى WebP حديث: يتولى المشفّر تلك الخطوة.</p>\n<p>افتح <a href=\"/ar/tahwil-as-sura-ila-base64/\">مشفّر الصورة إلى Base64</a> وارفع الملف المنزّل وانسخ السلسلة الجديدة بصيغة الإخراج التي تحتاجها. والسلسلة الجديدة أقصر من الأصلية عندما صغّر التحويل الملف: BMP محول إلى WebP قبل إعادة الترميز ينتج سلسلة أقصر بكثير من الأصلية.</p>\n<p>احتفظ بالسلسلتين حتى تتأكد من أن الجديدة تعمل: السلسلة الأصلية هي النسخة الوحيدة من الملف الأصلي، وحذفها قبل الاختبار مخاطرة غير ضرورية.</p>\n<h2 id=\"decoding-from-chat-and-documents\">كيف تفك صورًا من رسائل محادثة ومستندات</h2>\n<p>تطبيقات المحادثة وأدوات التعاون تعرض أحيانًا صورًا كسلاسل Base64 في بيانات رسائلها، خصوصًا في الروبوتات وwebhooks والمحادثات المصدّرة: نسخة ملصوقة من تلك البيانات تحمل الصورة مباشرة.</p>\n<p>وعند النسخ من تصدير محادثة، انتبه لأن السلسلة قد تنقسم إلى أسطر عدة أو تُلف بهروب JSON: الشرطات المائلة العكسية قبل الشرطات المائلة وعلامات الاقتباس هي آثار تصدير، لا جزء من السلسلة. والمستندات مصدر مشابه: ملف Word أو تصميم مصدّر قد يحتوي صورة مضمنة ككتلة Base64 داخل XML، ونسخ تلك الكتلة يعطيك الصورة مباشرة.</p>\n<p>ينطبق نفس تحذير القطع في كل مكان: سلسلة منسوخة من رسالة قُطعت في المنتصف لن تُفك، والحل الوحيد نسخة كاملة من المصدر. ولتصديرات محادثة كبيرة، فك صورة واحدة في كل مرة وغيّر اسم كل تنزيل فورًا: دفعة ملفات كلها اسمها decoded_image مربكة، بينما أسماء واضحة تحافظ على النظام.</p>\n<p>تذكر أن صورة مفككة من سجل محادثة قد تكون مصغرة بدل الأصل: راجع الأبعاد بجانب المعاينة قبل افتراض أن الملف عالي الدقة. وعندما تأتي السلسلة من نظام تتحكم فيه، فكر في تغيير السير لإرسال ملفات بدل سلاسل: نقل الملفات أكثر كفاءة، والرحلة ذهابًا وإيابًا أسرع.</p>\n<p>وعندما تأتي السلسلة من نظام لا تتحكم فيه، فك التشفير هو الخيار الوحيد، وهذه الأداة تتعامل معه محليًا دون رفع السلسلة إلى أي مكان.</p>\n<h2 id=\"quick-reference-checklist\">قائمة مرجعية سريعة</h2>\n<p>الصق السلسلة كاملة وراجع المعاينة وخلفية المربعات للشفافية، واختر الأصل أو PNG أو JPG أو WebP، ونزّل كـdecoded_image بالامتداد الصحيح.</p>\n<p>امسح الإدخال بين السلاسل وغيّر اسم التنزيلات فورًا واحتفظ بالسلسلة الأصلية حتى يُختبر الملف الجديد.</p>\n<p>للسياق الكامل، اقرأ <a href=\"/ar/blog/dalil-tahwil-base64-ila-sura/\">دليل تحويل Base64 إلى صورة الكامل</a>، وللمقارنة في الأداء راجع <a href=\"/ar/blog/base64-vs-malafat-as-suwar/\">Base64 مقابل ملفات الصور: الأداء وحالات الاستخدام</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل يمكنني فك سلسلة Base64 على هاتفي؟","answer":"نعم، يعمل المفكك في متصفحات الهاتف على iOS وAndroid: الصق السلسلة وراجع المعاينة ونزّل الصورة. وللسلاسل الطويلة جدًا، قد يكون اللصق بطيئًا، فاستخدم سلسلة أقصر أولًا أو جهاز حاسوب."},{"question":"ما أكبر سلسلة Base64 يمكنني فكها؟","answer":"لا حد ثابت في الأداة، لكن السلاسل الكبيرة جدًا تأخذ وقتًا أطول لأن المتصفح يجب أن يعالج كل النص ويعيد بناء البيانات الثنائية. وسلاسل عدة ميغابايت تعمل، مع أنها قد تكون بطيئة على أجهزة ضعيفة."},{"question":"لماذا للملف المفكك اسم مختلف عن الأصل؟","answer":"سلسلة Base64 لا تحمل اسم الملف الأصلي، فلا تستطيع الأداة معرفته. وكل تنزيل اسمه decoded_image بالامتداد المناسب. وغيّر اسم الملف فورًا بعد التنزيل ليبقى منظمًا."},{"question":"هل يمكنني فك سلسلة Base64 جاءت من PDF أو مستند Word؟","answer":"فقط إذا كانت السلسلة نفسها صورة Base64 صالحة. والمستندات غالبًا تحفظ الصور بأشكال أخرى، مثل بيانات ثنائية مضمنة أو تدفقات مضغوطة، ليست Base64. واستخرج الصورة من المستند أولًا ثم فكها."},{"question":"هل فك سلسلة Base64 يقلل جودتها؟","answer":"لا، فك التشفير هو عكس الترميز بالضبط، فالبايتات الخارجة هي البايتات الداخلة. وأي فقدان جودة حدث قبل الترميز، عندما ضُغطت الصورة أو حُولت، لا أثناء فك التشفير."},{"question":"ماذا أفعل إذا فُكت السلسلة لكن الصورة تبدو سيئة؟","answer":"راجع أولًا إن كنت نزّلت الصيغة الصحيحة: PNG شفاف منزّل كـJPG تُملأ شفافيته، وGIF متحرك محول إلى PNG يفقد حركته. ونزّل كأصل لرؤية الملف كما رُمّز بالضبط."}];
